  if (!si || !sw) return geo;
  const mapped = boneNames.map((n) => MAPPED.has(n)), tank = boneNames.indexOf('tank'), tankDrop = TANK_DROP();
  for (let i = 0; i < pos.count; i++) {
    let w = 0, wt = 0;
    for (let k = 0; k < 4; k++) {
