    pos.setY(i, y + w * (s3ProportionY(y) - y) + wt * tankDrop);
    if (nrm) {
      const k = 1 + w * (s3ProportionSlope(y) - 1);
      const nx = nrm.getX(i), ny = nrm.getY(i) / k, nz = nrm.getZ(i), l = Math.hypot(nx, ny, nz) || 1;
      nrm.setXYZ(i, nx / l, ny / l, nz / l);
